    [0,1,2,3,4,5,6,7],  # e
    [1,2,3,0,5,6,7,4],  # alpha
    [2,3,0,1,6,7,4,5],  # eta
    [3,0,1,2,7,4,5,6],  # beta
    [4,5,6,7,0,1,2,3],  # gamma
    [5,6,7,4,1,2,3,0],  # zeta
    [6,7,4,5,2,3,0,1],  # epsilon
    [7,4,5,6,3,0,1,2],  # delta
]

names = ['e','α','η','β','γ','ζ','ε','δ']

def is_subgroup(S):
    Sset = set(S)
    # closure
    for x in S:
        for y in S:
            if table[x][y] not in Sset:
                return False
    # inverses
    for x in S:
        found = False
        for y in S:
            if table[x][y] == 0:
                found = True
                break
        if not found:
            return False
    return True

subgroups = [
    [0],                          # {e}
    [0,2],                        # {e, eta}
