    [0,5,2,7],                    # {e, zeta, eta, delta}
    [0,2,4,6],                    # {e, eta, gamma, epsilon}
    [0,1,2,3,4,5,6,7],            # G
]

print("验证所有子群的封闭性和逆元：")
for i, S in enumerate(subgroups):
    ok = is_subgroup(S)
    print(f"  子群{i+1}: {{{', '.join(names[s] for s in S)}}} -> {'✓ 合法' if ok else '✗ 不合法'}")

